CREATE OR REPLACE FUNCTION public.guard_profile_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier')) THEN IF TG_OP='INSERT' THEN IF NEW.kyc_status <> 'not_started' OR NEW.org_verified THEN RAISE EXCEPTION 'Verification is assigned by reviewers only'; END IF; ELSIF NEW.kyc_status IS DISTINCT FROM OLD.kyc_status OR NEW.org_verified IS DISTINCT FROM OLD.org_verified THEN RAISE EXCEPTION 'Verification is assigned by reviewers only'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_verification BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_verification();
CREATE OR REPLACE FUNCTION public.guard_kyc_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier')) THEN IF TG_OP='INSERT' THEN IF NEW.status<>'pending' OR NEW.reviewer_id IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.reviewer_notes IS NOT NULL THEN RAISE EXCEPTION 'New identity submissions must await review'; END IF; ELSE IF NEW.status IS DISTINCT FROM OLD.status OR NEW.reviewer_id IS DISTINCT FROM OLD.reviewer_id OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at OR NEW.reviewer_notes IS DISTINCT FROM OLD.reviewer_notes THEN RAISE EXCEPTION 'Only reviewers can decide identity verification'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_kyc_review BEFORE INSERT OR UPDATE ON public.kyc_submissions FOR EACH ROW EXECUTE FUNCTION public.guard_kyc_review();
CREATE OR REPLACE FUNCTION public.sync_kyc_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles SET kyc_status=NEW.status,org_verified=(NEW.status='approved' AND NEW.org_certificate_url IS NOT NULL AND nullif(trim(NEW.org_registration_number),'') IS NOT NULL) WHERE id=NEW.user_id; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(coalesce(NEW.reviewer_id,NEW.user_id),'kyc.'||CASE WHEN TG_OP='INSERT' THEN 'submitted' ELSE NEW.status::text END,'kyc_submission',NEW.id,jsonb_build_object('user_id',NEW.user_id,'notes',NEW.reviewer_notes)); RETURN NEW; END $$;
CREATE TRIGGER sync_kyc_status AFTER INSERT OR UPDATE OF status ON public.kyc_submissions FOR EACH ROW EXECUTE FUNCTION public.sync_kyc_review();
CREATE POLICY "Verifiers update reviewed profiles" ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'verifier')) WITH CHECK(public.has_role(auth.uid(),'verifier'));
CREATE OR REPLACE FUNCTION public.guard_listing_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE reviewer boolean := auth.uid() IS NULL OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier'); BEGIN IF NOT reviewer THEN IF TG_OP='INSERT' THEN IF NEW.verification_status NOT IN ('pending','unverified') OR NEW.status NOT IN ('draft','pending_review') OR NEW.verified_by IS NOT NULL OR NEW.verified_at IS NOT NULL OR NEW.verification_notes IS NOT NULL THEN RAISE EXCEPTION 'Assets must be reviewed before publication'; END IF; ELSE IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.verification_status IS DISTINCT FROM OLD.verification_status OR NEW.verified_by IS DISTINCT FROM OLD.verified_by OR NEW.verified_at IS DISTINCT FROM OLD.verified_at OR NEW.verification_notes IS DISTINCT FROM OLD.verification_notes OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN ('draft','pending_review','withdrawn')) THEN RAISE EXCEPTION 'Only reviewers can approve or publish assets'; END IF; IF (NEW.title,NEW.ip_type,NEW.registration_number,NEW.registration_authority,NEW.jurisdictions,NEW.documents) IS DISTINCT FROM (OLD.title,OLD.ip_type,OLD.registration_number,OLD.registration_authority,OLD.jurisdictions,OLD.documents) AND OLD.verification_status='verified' THEN NEW.verification_status:='pending'; NEW.status:='pending_review'; NEW.verified_by:=NULL; NEW.verified_at:=NULL; NEW.verification_notes:=NULL; END IF; END IF; END IF; IF NEW.verification_status='verified' AND (TG_OP='INSERT' OR OLD.verification_status IS DISTINCT FROM NEW.verification_status) THEN IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.owner_id AND kyc_status='approved') THEN RAISE EXCEPTION 'Approve the rights-holder identity before publishing this asset'; END IF; IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.documents) d WHERE d->>'kind'='registration_certificate' AND nullif(d->>'path','') IS NOT NULL) THEN RAISE EXCEPTION 'A registration certificate is required before approval'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_listing_verification BEFORE INSERT OR UPDATE ON public.ip_listings FOR EACH ROW EXECUTE FUNCTION public.guard_listing_verification();
CREATE OR REPLACE FUNCTION public.log_listing_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.verification_status IS DISTINCT FROM OLD.verification_status THEN INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(coalesce(auth.uid(),NEW.verified_by,NEW.owner_id),'listing.'||NEW.verification_status::text,'ip_listing',NEW.id,jsonb_build_object('notes',NEW.verification_notes)); INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(NEW.owner_id,'listing_review','Asset review: '||NEW.title,'Status: '||NEW.verification_status::text||coalesce('. '||NEW.verification_notes,''),NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_listing_review AFTER UPDATE OF verification_status ON public.ip_listings FOR EACH ROW EXECUTE FUNCTION public.log_listing_review();
CREATE OR REPLACE FUNCTION public.decide_kyc(p_id uuid,p_status text,p_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier')) THEN RAISE EXCEPTION 'Reviewer access required'; END IF; IF p_status NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Invalid review decision'; END IF; UPDATE public.kyc_submissions SET status=p_status::public.kyc_status,reviewer_id=auth.uid(),reviewer_notes=p_notes,reviewed_at=now() WHERE id=p_id AND status='pending' AND user_id<>auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Submission is no longer pending or cannot be self-reviewed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_kyc(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_kyc(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.decide_listing(p_id uuid,p_status text,p_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier')) THEN RAISE EXCEPTION 'Reviewer access required'; END IF; IF p_status NOT IN ('verified','rejected') THEN RAISE EXCEPTION 'Invalid review decision'; END IF; UPDATE public.ip_listings SET verification_status=p_status::public.verification_status,verification_notes=p_notes,verified_by=auth.uid(),verified_at=now(),status=CASE WHEN p_status='verified' THEN 'active'::public.listing_status ELSE 'withdrawn'::public.listing_status END WHERE id=p_id AND verification_status IN ('pending','unverified') AND owner_id<>auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Listing is no longer pending or cannot be self-reviewed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_listing(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_listing(uuid,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.guard_profile_verification(), public.guard_kyc_review(),public.sync_kyc_review(),public.guard_listing_verification(),public.log_listing_review() FROM PUBLIC,anon,authenticated;